INSERT INTO `products` (`id`, `supplier_id`, `category_id`, `name`, `description`, `status`, `created_at`, `updated_at`) VALUES
(1, 1, 5, 'Áo Thun Tay Ngắn Trơn Màu', 'Áo thun tay ngắn chất liệu cotton 100%, thoáng mát, phù hợp với thời tiết Việt Nam. Có nhiều màu sắc bắt mắt cho bé.', 'active', '2026-03-09 21:01:00', '2026-03-09 21:01:00'),
(2, 1, 5, 'Áo Thun In Hình Hoạt Hình', 'Áo thun in hình nhân vật hoạt hình yêu thích của bé. Chất lượng in sắc nét, không bay màu sau giặt.', 'active', '2026-03-09 21:01:00', '2026-03-09 21:01:00'),
(3, 1, 6, 'Quần Shorts Kaki Trẻ Em', 'Quần shorts kaki chất lượng cao, co giãn tốt, có túi hộp tiện lợi. Độ bền cao, không xù lông.', 'active', '2026-03-09 21:01:00', '2026-03-09 21:01:00'),
(4, 2, 8, 'Ô Tô Điều Khiển Từ Xa', 'Xe ô tô điều khiển từ xa chạy bằng pin, tốc độ nhanh, khả năng cơ động cao. An toàn cho bé từ 4 tuổi trở lên.', 'active', '2026-03-09 21:01:00', '2026-03-09 21:01:00'),
(5, 2, 8, 'Xe Tải Kéo Trẻ Em', 'Xe tải kéo chất liệu nhựa an toàn, có bánh xe xoay trơn, phù hợp cho bé từ 1 tuổi.', 'active', '2026-03-09 21:01:00', '2026-03-09 21:01:00'),
(6, 2, 9, 'Búp Bê Barbie Xinh Đẹp', 'Búp bê Barbie kinh điển với trang phục xinh đẹp, tóc dài vàng. Phụ kiện đi kèm đủ đầy.', 'active', '2026-03-09 21:01:00', '2026-03-09 21:01:00'),
(7, 2, 10, 'Bộ Xếp Hình Lego 100+ Mảnh', 'Bộ xếp hình Lego với 100+ mảnh, giúp bé phát triển sự sáng tạo và tư duy không gian.', 'active', '2026-03-09 21:01:00', '2026-03-09 21:01:00'),
(8, 1, 11, 'Giày Thể Thao Sneaker Trẻ Em', 'Giày sneaker nhẹ, thoáng khí, có đệm êm chân. Thiết kế hiện đại phù hợp với bé trai và bé gái.', 'active', '2026-03-09 21:01:00', '2026-03-09 21:01:00'),
(9, 1, 13, 'Mũ Lưỡi Trai Trẻ Em', 'Mũ lưỡi trai vải cotton mềm mại, có nắp có thể điều chỉnh kích thước, bảo vệ da bé khỏi nắng.', 'active', '2026-03-09 21:01:00', '2026-03-09 21:01:00');

